#!/usr/bin/env node

import { execFileSync, spawn, spawnSync } from 'node:child_process'
import { existsSync, readFileSync, realpathSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)))
const require = createRequire(import.meta.url)

// Lockfiles are regenerated by the package manager as a side effect of
// `install`, so a checkout that's been built or updated once carries a dirty,
// machine-authored lockfile. That drift makes `git pull --ff-only` abort with
// "local changes would be overwritten by merge" — the exact failure users hit
// running `praxis --update`. Since the update reinstalls right after pulling
// (regenerating the lockfile against the new package.json), it's safe to
// discard the drift first. Kept as a pure helper so it's unit-testable.
const LOCKFILES = new Set([
  'bun.lock',
  'bun.lockb',
  'package-lock.json',
  'npm-shrinkwrap.json',
  'yarn.lock',
  'pnpm-lock.yaml',
])

/**
 * Given `git status --porcelain` output, return the tracked lockfiles that are
 * dirty (staged and/or unstaged) and should be restored to HEAD before a pull.
 * Untracked ('??') entries are ignored — there's nothing at HEAD to restore.
 */
export function lockfilesToRestore(porcelain) {
  const restore = []
  for (const line of String(porcelain).split('\n')) {
    if (line.length < 4) continue
    const status = line.slice(0, 2)
    if (status === '??') continue
    // porcelain paths start at column 3; renames read "old -> new" (not a
    // lockfile concern, but take the post-rename path if it ever occurs).
    const raw = line.slice(3).trim()
    const path = raw.includes(' -> ') ? raw.slice(raw.indexOf(' -> ') + 4) : raw
    if (LOCKFILES.has(path)) restore.push(path)
  }
  return restore
}

function detectPackageManager() {
  const check = spawnSync('bun', ['--version'], { stdio: 'ignore' })
  return !check.error && check.status === 0 ? 'bun' : 'npm'
}

function usage() {
  return `Usage: praxis [command]

Commands:
  praxis              Launch Praxis (builds first if needed)
  praxis serve <repo>  Run Praxis in the local browser
    --remote           Share securely with other devices in your Tailscale network
    --remote-port=8443 Choose the tailnet HTTPS port (preview uses the next port)
  praxis --update      Pull latest changes, reinstall, and rebuild
  praxis --help        Show this help message
  praxis --version      Print the installed version
`
}

export function parseTailscaleStatus(raw) {
  let status
  try {
    status = JSON.parse(String(raw))
  } catch {
    throw new Error('Tailscale did not return valid status JSON.')
  }
  if (status.BackendState && status.BackendState !== 'Running') {
    throw new Error(`Tailscale is not connected (state: ${status.BackendState}).`)
  }
  const hostname = String(status.Self?.DNSName ?? '').replace(/\.$/, '')
  if (!hostname.endsWith('.ts.net')) {
    throw new Error('Tailscale MagicDNS is required for secure remote access.')
  }
  return hostname
}

export function tailscaleServeEnableUrl(raw) {
  let status
  try {
    status = JSON.parse(String(raw))
  } catch {
    throw new Error('Tailscale did not return valid status JSON.')
  }
  const hostname = parseTailscaleStatus(raw)
  if (Array.isArray(status.CertDomains) && status.CertDomains.includes(hostname)) return null
  const nodeId = String(status.Self?.ID ?? '')
  return nodeId ? `https://login.tailscale.com/f/serve?node=${encodeURIComponent(nodeId)}` : null
}

export function remoteServeSpec(hostname, localPort, previewLocalPort, remotePort = 8443) {
  const ports = [localPort, previewLocalPort, remotePort, remotePort + 1]
  if (ports.some((port) => !Number.isInteger(port) || port < 1 || port > 65535)) {
    throw new Error('Remote access ports must be integers between 1 and 65535.')
  }
  if (localPort === previewLocalPort) throw new Error('Control and preview ports must differ.')
  return {
    publicOrigin: `https://${hostname}:${remotePort}`,
    previewPublicOrigin: `https://${hostname}:${remotePort + 1}`,
    routes: [
      {
        externalPort: remotePort,
        target: `http://127.0.0.1:${localPort}`
      },
      {
        externalPort: remotePort + 1,
        target: `http://127.0.0.1:${previewLocalPort}`
      }
    ]
  }
}

function tailscale(args, options = {}) {
  const result = spawnSync('tailscale', args, { encoding: 'utf8', ...options })
  if (result.error || result.status !== 0) {
    const detail = String(result.stderr || result.stdout || result.error?.message || '').trim()
    throw new Error(detail || `tailscale ${args.join(' ')} failed.`)
  }
  return String(result.stdout ?? '')
}

function configureRemoteAccess(localPort, previewLocalPort, remotePort) {
  let hostname
  let statusJson
  try {
    statusJson = tailscale(['status', '--json'])
    hostname = parseTailscaleStatus(statusJson)
  } catch (error) {
    throw new Error(
      `Remote mode needs a connected Tailscale client. ${error instanceof Error ? error.message : String(error)}`
    )
  }
  const enableUrl = tailscaleServeEnableUrl(statusJson)
  if (enableUrl) {
    throw new Error(`Tailscale Serve is not enabled. Enable it once, then rerun:\n${enableUrl}`)
  }

  const spec = remoteServeSpec(hostname, localPort, previewLocalPort, remotePort)
  const status = tailscale(['serve', 'status'])
  for (const route of spec.routes) {
    if (new RegExp(`:${route.externalPort}(?:\\D|$)`).test(status)) {
      throw new Error(
        `Tailscale Serve port ${route.externalPort} is already configured. Choose another with --remote-port.`
      )
    }
  }

  const configured = []
  const cleanup = () => {
    for (const port of configured.reverse()) {
      spawnSync('tailscale', ['serve', '--yes', `--https=${port}`, 'off'], {
        stdio: 'ignore'
      })
    }
    configured.length = 0
  }
  try {
    for (const route of spec.routes) {
      tailscale(['serve', '--bg', '--yes', `--https=${route.externalPort}`, route.target])
      configured.push(route.externalPort)
    }
  } catch (error) {
    cleanup()
    throw new Error(
      `Could not configure Tailscale Serve. ${error instanceof Error ? error.message : String(error)}`
    )
  }
  return { ...spec, cleanup }
}

function getElectronPath() {
  try {
    return require('electron')
  } catch {
    console.error(`Praxis isn't installed yet — run: ${detectPackageManager()} install`)
    process.exit(1)
  }
}

function printVersion() {
  const pkgPath = join(repoRoot, 'package.json')
  const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'))
  console.log(`Praxis ${pkg.version}`)
}

function launch() {
  const builtEntry = join(repoRoot, 'out', 'main', 'index.js')

  if (!existsSync(builtEntry)) {
    const buildResult = spawnSync(detectPackageManager(), ['run', 'build'], {
      cwd: repoRoot,
      stdio: 'inherit',
    })
    if (buildResult.status !== 0) {
      console.error('Praxis build failed — see output above.')
      process.exit(buildResult.status ?? 1)
    }
  }

  const electronPath = getElectronPath()

  const child = spawn(electronPath, ['.'], {
    cwd: repoRoot,
    detached: true,
    stdio: 'ignore',
  })
  child.unref()

  console.log('Launching Praxis…')
  process.exit(0)
}

function serve(args) {
  const positional = args.filter((arg) => !arg.startsWith('--'))
  const requestedRoot = positional[0] || process.cwd()
  let root
  try {
    root = realpathSync(requestedRoot)
  } catch {
    console.error(`Project folder not found: ${requestedRoot}`)
    process.exit(1)
  }

  const portFlag = args.find((arg) => arg.startsWith('--port='))
  const port = portFlag ? Number(portFlag.slice('--port='.length)) : 4173
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    console.error(`Invalid browser port: ${portFlag?.slice('--port='.length)}`)
    process.exit(1)
  }

  const remote = args.includes('--remote')
  const previewPortFlag = args.find((arg) => arg.startsWith('--preview-port='))
  const previewPort = previewPortFlag
    ? Number(previewPortFlag.slice('--preview-port='.length))
    : port + 1
  const remotePortFlag = args.find((arg) => arg.startsWith('--remote-port='))
  const remotePort = remotePortFlag ? Number(remotePortFlag.slice('--remote-port='.length)) : 8443
  if (remote && port < 1) {
    console.error('Remote mode needs a fixed browser port between 1 and 65535.')
    process.exit(1)
  }
  if (
    remote &&
    (!Number.isInteger(previewPort) ||
      previewPort < 1 ||
      previewPort > 65535 ||
      previewPort === port)
  ) {
    console.error(
      `Invalid preview port: ${previewPortFlag?.slice('--preview-port='.length) ?? previewPort}`
    )
    process.exit(1)
  }
  if (remote && (!Number.isInteger(remotePort) || remotePort < 1 || remotePort >= 65535)) {
    console.error(
      `Invalid remote port: ${remotePortFlag?.slice('--remote-port='.length) ?? remotePort}`
    )
    process.exit(1)
  }

  const builtEntry = join(repoRoot, 'out', 'main', 'index.js')
  const rendererEntry = join(repoRoot, 'out', 'renderer', 'index.html')
  if (!existsSync(builtEntry) || !existsSync(rendererEntry)) {
    const buildResult = spawnSync(detectPackageManager(), ['run', 'build'], {
      cwd: repoRoot,
      stdio: 'inherit',
    })
    if (buildResult.status !== 0) {
      console.error('Praxis build failed — see output above.')
      process.exit(buildResult.status ?? 1)
    }
  }

  const electronPath = getElectronPath()
  let remoteAccess
  if (remote) {
    try {
      remoteAccess = configureRemoteAccess(port, previewPort, remotePort)
    } catch (error) {
      console.error(error instanceof Error ? error.message : String(error))
      process.exit(1)
    }
    console.log(`Tailscale remote access: ${remoteAccess.publicOrigin}`)
  }

  const child = spawn(electronPath, ['.'], {
    cwd: repoRoot,
    stdio: 'inherit',
    env: {
      ...process.env,
      PRAXIS_WEB_MODE: '1',
      PRAXIS_WEB_ROOT: root,
      PRAXIS_WEB_PORT: String(port),
      PRAXIS_WEB_PREVIEW_PORT: remote ? String(previewPort) : '0',
      // In remote mode the one-time URL belongs on the other device. Opening it
      // locally would consume the launch token before that browser can pair.
      PRAXIS_WEB_OPEN: remote || args.includes('--no-open') ? '0' : '1',
      ...(remoteAccess
        ? {
            PRAXIS_WEB_REMOTE: '1',
            PRAXIS_WEB_PUBLIC_ORIGIN: remoteAccess.publicOrigin,
            PRAXIS_WEB_PREVIEW_ORIGIN: remoteAccess.previewPublicOrigin,
          }
        : {})
    },
  })
  let stopping = false
  const stop = (signal) => {
    if (stopping) return
    stopping = true
    remoteAccess?.cleanup()
    child.kill(signal)
  }
  process.once('SIGINT', () => stop('SIGINT'))
  process.once('SIGTERM', () => stop('SIGTERM'))
  child.on('error', (error) => {
    remoteAccess?.cleanup()
    console.error(`Could not start Praxis browser mode: ${error.message}`)
    process.exit(1)
  })
  child.on('exit', (code, signal) => {
    remoteAccess?.cleanup()
    process.exit(signal ? 1 : (code ?? 0))
  })
}

function update() {
  let before
  try {
    before = execFileSync('git', ['rev-parse', '--short', 'HEAD'], {
      cwd: repoRoot,
    })
      .toString()
      .trim()
  } catch {
    console.error('Could not determine current git revision.')
    process.exit(1)
  }

  // Drop machine-generated lockfile drift so `git pull --ff-only` doesn't abort
  // on it; `install` below rebuilds the lockfile against the pulled package.json.
  const status = spawnSync('git', ['status', '--porcelain'], {
    cwd: repoRoot,
    encoding: 'utf8',
  })
  if (status.status === 0) {
    const dirtyLocks = lockfilesToRestore(status.stdout)
    if (dirtyLocks.length > 0) {
      console.log(
        `Discarding local ${dirtyLocks.join(', ')} changes (regenerated on install)…`,
      )
      spawnSync('git', ['checkout', 'HEAD', '--', ...dirtyLocks], {
        cwd: repoRoot,
        stdio: 'inherit',
      })
    }
  }

  const pm = detectPackageManager()
  const steps = [
    ['git', ['pull', '--ff-only']],
    [pm, ['install']],
    [pm, ['run', 'build']],
  ]

  for (const [cmd, args] of steps) {
    const result = spawnSync(cmd, args, { cwd: repoRoot, stdio: 'inherit' })
    if (result.status !== 0) {
      console.error(
        `Update failed while running \`${cmd} ${args.join(' ')}\` (exit code ${result.status}).` +
          (cmd === 'git'
            ? ' If you have local changes, commit or stash them and try again.'
            : ''),
      )
      process.exit(result.status ?? 1)
    }
  }

  const after = execFileSync('git', ['rev-parse', '--short', 'HEAD'], {
    cwd: repoRoot,
  })
    .toString()
    .trim()

  if (before === after) {
    console.log('Praxis is already up to date.')
  } else {
    console.log(`Updated ${before} → ${after}.`)
  }

  console.log('Run `praxis` to (re)start.')
  process.exit(0)
}

function main() {
  const args = process.argv.slice(2)
  const command = args[0]

  if (command === undefined) {
    launch()
    return
  }

  if (command === '--update' || command === 'update') {
    // --no-launch is accepted (passed by the in-app updater) and ignored,
    // since update() never auto-launches regardless.
    update()
    return
  }

  if (command === 'serve') {
    serve(args.slice(1))
    return
  }

  if (command === '--help' || command === '-h') {
    console.log(usage())
    process.exit(0)
    return
  }

  if (command === '--version' || command === '-v') {
    printVersion()
    process.exit(0)
    return
  }

  console.error(`Unknown command: ${command}\n`)
  console.error(usage())
  process.exit(1)
}

// Run the CLI only when invoked as a script (directly or via the PATH symlink
// install.sh creates), not when imported by a test. realpath both sides so the
// symlink and its target compare equal. Default to running on any error — a
// real CLI invocation always has a resolvable argv[1], so a throw here only
// happens in edge cases where no-op'ing the command would be worse.
function invokedAsScript() {
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))
  } catch {
    return true
  }
}

if (invokedAsScript()) main()
